package local.ttlab.gallery;
import android.app.AlertDialog;import android.view.View;import android.widget.*;import java.util.*;import java.util.function.Consumer;
final class SavedCollectionsUi {
 private static boolean active(SecureActivity a,State s){return a.biometricCurrent(a.unlockEpoch())&&a.state==s&&s.unlocked&&!a.isFinishing()&&!a.isDestroyed();}
 static void list(SecureActivity a,State s,Consumer<MediaFilter> apply,boolean manage){s.database.execute(()->{try{List<SavedCollection> rows=s.library.collections();a.runOnUiThread(()->{if(!active(a,s))return;List<String> labels=new ArrayList<>();for(SavedCollection row:rows)labels.add(row.name);if(labels.isEmpty()){Toast.makeText(a,"Aún no hay filtros guardados. Abre Filtrar y ordenar y pulsa Guardar filtros.",Toast.LENGTH_LONG).show();return;}if(!manage)labels.add("Gestionar filtros");GalleryUi.menu(a,"Filtros guardados · "+SourceId.label(s.key),labels.toArray(new String[0]),n->{if(n==rows.size()){list(a,s,apply,true);return;}SavedCollection row=rows.get(n);if(!manage)apply.accept(row.filter.copy());else GalleryUi.menu(a,row.name,new String[]{"Aplicar filtro","Renombrar","Eliminar filtro"},action->{if(action==0)apply.accept(row.filter.copy());else if(action==1)name(a,s,row.id,row.name,row.filter);else{AlertDialog confirm=new SecureDialogs.Builder(a).setTitle("¿Eliminar este filtro guardado?").setMessage("Se elimina la consulta guardada. Tus archivos y marcas se conservan.").setNegativeButton("Conservar",null).setPositiveButton("Eliminar",(d,w)->s.database.execute(()->{try{if(active(a,s))s.library.deleteCollection(row.id);}catch(Exception failure){a.runOnUiThread(()->{if(active(a,s))Toast.makeText(a,"No se pudo eliminar el filtro. Reintenta.",Toast.LENGTH_LONG).show();});}})).create();a.trackPrivateDialog(confirm);confirm.show();}});});});}catch(Exception failure){a.runOnUiThread(()->{if(active(a,s))Toast.makeText(a,"No se pudieron leer los filtros guardados. Reintenta.",Toast.LENGTH_LONG).show();});}});}
 static void name(SecureActivity a,State s,long id,String original,MediaFilter filter){MediaFilter snapshot=filter.copy();EditText input=new EditText(a);input.setHint("Nombre del filtro");input.setSingleLine(true);input.setText(original);input.setSaveEnabled(false);input.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);input.setImeOptions(android.view.inputmethod.EditorInfo.IME_FLAG_NO_PERSONALIZED_LEARNING);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(60)});LinearLayout box=new LinearLayout(a);int padding=Math.round(24*a.getResources().getDisplayMetrics().density);box.setPadding(padding,0,padding,0);box.addView(input,new LinearLayout.LayoutParams(-1,-2));AlertDialog dialog=new SecureDialogs.Builder(a).setTitle(id==0?"Guardar filtro":"Renombrar filtro").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",null).create();a.trackPrivateDialog(dialog);dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String proposed;try{proposed=SavedCollection.checkedName(input.getText().toString());SavedCollection.encode(snapshot);}catch(IllegalArgumentException invalid){input.setError(invalid.getMessage());return;}dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);s.database.execute(()->{try{if(!active(a,s))return;s.library.saveCollection(id,proposed,snapshot);a.runOnUiThread(()->{if(active(a,s)){dialog.dismiss();Toast.makeText(a,"Filtro guardado",Toast.LENGTH_SHORT).show();}});}catch(Exception failure){a.runOnUiThread(()->{if(active(a,s)){dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(true);input.setError(failure instanceof IllegalStateException?failure.getMessage():"No se pudo guardar. Reintenta.");}});}});}));dialog.show();}
}
